using Microsoft.Dynamics365.LocalizationFramework;

/// <summary>
/// MPJ_30779_PaymentPlus
/// <c>METERFormatDestinationAzureStorageSettings</c> manages the settings for new ER destination for 'MET Azure Storage'
/// </summary>
public class METERFormatDestinationAzureStorageSettings implements ERIFormatFileDestinationSettings
{
    internal const str SettingsKey = classStr(METERFormatDestinationAzureStorageSettings);
    public const int CurrentVersion = 1;

    private boolean isEnabled;
    private boolean isEncrypted;
    private boolean overwrite;
    private DocuTypeId docuTypesId;

}

Method.Source:
[Hookable(false)]
public DocuTypeId parmDocuTypeId(DocuTypeId _docuTypesId = docuTypesId)
{
    docuTypesId = _docuTypesId;
    return docuTypesId;
}

[Hookable(false)]
public boolean parmIsEnabled(boolean _value = isEnabled)
{
    isEnabled = _value;
    return isEnabled;
}

[Hookable(false)]
public boolean parmIsEncrypted(boolean _value = isEncrypted)
{
    isEncrypted = _value;
    return isEncrypted;
}

[Hookable(false)]
public boolean parmOverwrite(boolean _value = overwrite)
{
    overwrite = _value;
    return overwrite;
}

/// <summary>
/// Validates Azure storage settings.
/// </summary>
[Hookable(false)]
public void validate()
{
    if (!docuTypesId)
    {
        throw error("@MET:DocuTypeAzureStorageRequired");
    }
}

[Hookable(false)]
public ERIFileDestination createDestination(ERDestinationExecutionContext _destinationContext, boolean _isGrouped)
{
    METERFileDestinationAzureStorage ret = new METERFileDestinationAzureStorage(this.parmDocuTypeId());
    ret.parmIsEncrypted(this.parmIsEncrypted());
    ret.parmOverwrite(this.parmOverwrite());
    return ret;
}

[Hookable(false)]
public container pack()
{
    return [CurrentVersion, docuTypesId, isEnabled, isEncrypted];
}

[Hookable(false)]
public boolean unpack(container packedClass)
{
    int version = RunBase::getVersion(packedClass);
    switch (version)
    {
        case CurrentVersion:
            [version, docuTypesId, isEnabled, isEncrypted] = packedClass;
            return true;
        default:
            return false;
    }
}

/// <summary>
/// Creates a new instance of an objected from a packed class container.
/// </summary>
/// <param name = "_packedClass">A packed class container.</param>
/// <returns>The new instance of an object.</returns>
public static METERFormatDestinationAzureStorageSettings create(container _packedClass)
{
    var ret = new METERFormatDestinationAzureStorageSettings();
    ret.unpack(_packedClass);
    return ret;
}
